"""Build three local approval-only concert diplomas using the approved logo."""
from pathlib import Path
import argparse,shutil

p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--keyboard-reference',type=Path,required=True);a=p.parse_args()
out=a.output.resolve();out.mkdir(parents=True,exist_ok=True)
repo=Path(__file__).resolve().parents[1]
shutil.copytree(repo/'fonts',out/'fonts',dirs_exist_ok=True)
shutil.copy2(repo/'assets/studio-logo-horizontal-720.webp',out/'logo.webp')
shutil.copy2(a.keyboard_reference,out/'keyboard-reference.jpeg')

def keyboard():
 # Clip only the original keyboard strip; do not redraw or alter its pixels.
 return '<img src="keyboard-reference.jpeg" alt="" aria-hidden="true">'

def music():
 parts=['<svg viewBox="0 0 610 180" aria-hidden="true">']
 for i in range(5):parts.append(f'<path d="M-15 {75+i*12} C160 {5+i*12},330 {155+i*12},625 {40+i*12}" fill="none" stroke="currentColor" stroke-width="1" opacity=".45"/>')
 for x,y in [(85,70),(175,72),(280,110),(390,105),(505,83)]:parts.append(f'<ellipse cx="{x}" cy="{y}" rx="8" ry="5" transform="rotate(-20 {x} {y})" fill="currentColor"/><path d="M{x+7} {y}v-38" stroke="currentColor" stroke-width="2"/>')
 return ''.join(parts)+'</svg>'

css='''@font-face{font-family:Prata;src:url(fonts/Prata.woff2)}@font-face{font-family:Onest;src:url(fonts/Onest.woff2);font-weight:100 900}*{box-sizing:border-box}body{margin:0;background:#e7e5df;color:#292c25;font-family:Onest,sans-serif}.tools{max-width:850px;margin:20px auto;padding:14px;line-height:1.5;text-align:center}.tools a,.tools button{display:inline-block;min-height:44px;padding:12px 20px;border:1px solid #7d846c;border-radius:24px;color:inherit;background:white;font:inherit;text-decoration:none;cursor:pointer}.sheet{width:210mm;height:297mm;position:relative;overflow:hidden;margin:20px auto;background:#faf7ef;--accent:#9c8456}.keys{position:absolute;left:0;top:0;bottom:0;width:24mm;border-right:3px solid var(--accent)}.keys svg{width:100%;height:100%}.frame{position:absolute;inset:9mm 9mm 9mm 30mm;border:1px solid #c9bea5}.content{position:absolute;inset:18mm 17mm 18mm 39mm;text-align:center}.logo{width:80mm;height:auto;display:block;margin:0 auto}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:3px;margin:14px 0 0}.rule{width:36px;height:2px;background:var(--accent);margin:35px auto 27px}h1{font:400 73px/1.1 Prata,serif;margin:0;letter-spacing:3px}.subtitle{font-size:11px;letter-spacing:3px;text-transform:uppercase;margin:20px 0 34px}.awarded{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--accent);margin:0 0 16px}.name{font:400 29px/1.4 Prata,serif;min-height:55px;border-bottom:1px solid #b7ac91;padding:5px 0}.reason{font-size:18px;line-height:1.7;margin:24px auto 10px;max-width:470px}.event{font:400 22px/1.5 Prata,serif;min-height:45px;border-bottom:1px solid #c9bea5;padding:4px 0}.thanks{font-size:14px;line-height:1.9;margin:27px auto 0;max-width:430px}.music{position:absolute;left:0;right:0;bottom:115px;color:var(--accent)}.footer{position:absolute;bottom:0;left:0;right:0;display:flex;gap:30px;text-align:left;font-size:11px;line-height:1.6}.footer>div{flex:1}.line{min-height:34px;border-bottom:1px solid #b7ac91;padding:5px 0}.city{font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-top:12px}.caption{margin-top:7px}[contenteditable]:empty:before{content:attr(data-placeholder);color:#929681}[contenteditable]:focus{outline:2px dashed var(--accent);outline-offset:5px}.green{background:#eff2e6;--accent:#6e8149}.green .frame{border:0;border-top:4px solid #6e8149;border-bottom:1px solid #a3b28a;inset:10mm 10mm 10mm 31mm}.green .keys{width:19mm;opacity:.9}.green .content{left:35mm}.green:before,.green:after{content:'';position:absolute;border:1px solid #bdcba5;border-radius:50%;width:420px;height:420px;right:-210px;bottom:170px}.green:after{width:500px;height:500px;right:-250px;bottom:130px}.green h1{font-size:70px;color:#405232}.green .rule{width:70px;margin-top:32px}.green .music{bottom:120px}.green .thanks{max-width:350px}.night{background:#172b2c;color:#fcf5e5;--accent:#d5b77a}.night .keys{width:26mm;border-color:#d5b77a}.night .frame{border-color:#718172;inset:10mm 10mm 10mm 32mm}.night .logo{background:#faf7ef;border-radius:6px;padding:7px;width:84mm}.night .content{left:40mm}.night .name,.night .event,.night .line{border-color:#89917b}.night .subtitle{color:#dfcba1}.night [contenteditable]:empty:before{color:#b1bba7}.night .music{bottom:118px}.spark{position:absolute;color:#d5b77a;font-size:22px;right:35px;top:240px}.night:after{content:'✦';position:absolute;right:58px;bottom:235px;color:#d5b77a;font-size:33px}.night .thanks{color:#e1dccb}@page{size:A4;margin:0}@media print{body{background:white}.tools{display:none}.sheet{margin:0;zoom:1!important}[contenteditable]:empty:before{content:''}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'''
# Reference keyboard is 285 of 905 pixels wide; A4 matches the source aspect ratio.
css += """.sheet .keys{width:66.13mm;border:0;overflow:hidden;opacity:1}.keys img{display:block;position:absolute;left:0;top:0;width:210mm;height:297mm;max-width:none}.sheet .frame{left:71mm}.sheet .content{left:76mm;right:12mm}.sheet .logo{width:70mm}.night .logo{width:74mm}.sheet h1{font-size:60px;letter-spacing:1px}.sheet .subtitle{font-size:10px;letter-spacing:2px}.sheet .name{font-size:25px}.sheet .reason{font-size:16px}.sheet .event{font-size:21px}.sheet .thanks{font-size:13px}.sheet .footer{gap:18px;font-size:10px}"""
options=[('01','classic','Тихая классика','Кремовая бумага, строгая рамка, клавиши слева и тонкий золотистый нотный стан. Универсальный вариант для любого концерта.'),('02','green','Музыка растёт','Светлый зелёный, клавиатура из референса и воздушные музыкальные линии. Праздничный вариант для детских выступлений.'),('03','night','Свет сцены','Глубокий зелёный, золотистые акценты и небольшие звёзды. Торжественный вариант для отчётного концерта; плотная заливка требует больше краски.')]
for num,cls,title,desc in options:
 html=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{num} · {title} — диплом участника концерта</title><style>{css}</style></head><body><div class="tools"><strong>{num} · {title}</strong><p>{desc}</p><p>На согласование. Поля можно заполнить нажатием. Подпись — только вручную.</p><a href="index.html">Все варианты</a> <button onclick="print()">Печать / PDF</button></div><main class="sheet {cls}"><div class="keys">{keyboard()}</div><div class="frame"></div>{'<span class="spark">✦</span>' if cls=='night' else ''}<div class="content"><img class="logo" src="logo.webp" width="302" height="101" alt="Музыка на кончиках пальцев"><p class="eyebrow">Студия фортепиано · Сургут</p><div class="rule"></div><h1>Диплом</h1><p class="subtitle">участника концерта</p><p class="awarded">награждается</p><div class="name" contenteditable="true" role="textbox" aria-label="Имя и фамилия ученика" data-placeholder="Имя и фамилия ученика"></div><p class="reason">за выступление в концерте студии<br>«Музыка на кончиках пальцев»</p><div class="event" contenteditable="true" role="textbox" aria-label="Название концерта" data-placeholder="Название концерта"></div><p class="thanks">Спасибо за музыку, которой вы делитесь,<br>старание и смелость выйти на сцену.</p><div class="music">{music()}</div><div class="footer"><div><div class="line" contenteditable="true" role="textbox" aria-label="Дата концерта" data-placeholder="Дата концерта"></div><div class="caption">Дата</div><div class="city">Сургут</div></div><div><div class="line"></div><div class="caption">Руководитель студии<br>Н. В. Пужалина</div></div></div></div></main><script>function fit(){{document.querySelector('.sheet').style.zoom=Math.min(1,(innerWidth-16)/794)}}addEventListener('resize',fit);fit()</script></body></html>'''
 (out/f'variant-{num}.html').write_text(html,encoding='utf-8')
cards=''.join(f'<article><a href="variant-{n}.html"><img src="variant-{n}.png" alt="Вариант {n}: {title}"></a><h2>{n} · {title}</h2><p>{desc}</p><a href="variant-{n}.html">Открыть и заполнить</a> · <a href="variant-{n}.pdf">PDF A4</a></article>' for n,c,title,desc in options)
(out/'index.html').write_text(f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Три варианта диплома за выступление</title><style>@font-face{{font-family:Onest;src:url(fonts/Onest.woff2)}}*{{box-sizing:border-box}}body{{background:#eeece5;color:#293023;margin:0;font:16px/1.6 Onest,sans-serif}}main{{max-width:1400px;margin:auto;padding:32px 24px}}h1{{font-size:clamp(28px,4vw,46px);line-height:1.2}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}}article{{background:#faf8f1;padding:18px;border-radius:14px}}img{{width:100%;height:auto}}h2{{font-size:23px}}a{{color:#3d5732;text-underline-offset:4px;display:inline-block;padding:10px 0}}.note{{max-width:850px;margin-bottom:30px}}@media(max-width:850px){{.grid{{grid-template-columns:1fr}}}}</style></head><body><main><a href="../index.html">← Материалы на согласование</a><h1>Диплом за выступление</h1><p class="note">Три варианта с утверждённым логотипом сайта и клавишами слева. Все — A4, с полями для имени, названия концерта и даты. Это диплом участника концерта, не документ об окончании обучения. Ничего не опубликовано.</p><div class="grid">{cards}</div><p class="note">Предлагаю № 01 как основной универсальный бланк; № 02 — для детских концертов, № 03 — для торжественных выступлений. Выберите вариант или укажите элементы, которые хотите объединить. PDF — пустые бланки; поля заполняются в HTML и печатаются через браузер.</p></main></body></html>''',encoding='utf-8')
print(out)
